<div class="community-chat" data-community-chat>
    <section class="community-chat-panel" id="community-chat-panel" aria-labelledby="community-chat-title" hidden>
        <header class="community-chat-header">
            <div><span class="community-chat-kicker">COMMUNITY</span><h2 id="community-chat-title" tabindex="-1">Community chat</h2><p>Discuss your experience with Simora.</p></div>
            <button type="button" class="community-chat-close" data-chat-close aria-label="Collapse community chat"><i class="bi bi-chevron-down" aria-hidden="true"></i></button>
        </header>
        <div class="community-chat-content">
            <div class="community-chat-notice" role="status"><i class="bi bi-info-circle" aria-hidden="true"></i><span>Preview only. Community messaging will be available when accounts and chat are connected.</span></div>
            <div class="community-chat-empty"><span class="community-chat-empty-icon"><i class="bi bi-chat-dots" aria-hidden="true"></i></span><h3>Start a conversation</h3><p>This space will bring everyone together to share their experiences.</p></div>
        </div>
        <div class="community-chat-composer">
            <label for="community-chat-message">Your message</label>
            <textarea id="community-chat-message" rows="2" placeholder="Messaging is not available yet" disabled aria-describedby="community-chat-unavailable"></textarea>
            <div class="community-chat-composer-footer"><span id="community-chat-unavailable">Messaging is unavailable in this preview.</span><button type="button" disabled>Send <i class="bi bi-arrow-up" aria-hidden="true"></i></button></div>
        </div>
    </section>
    <button type="button" class="community-chat-fab" data-chat-toggle aria-label="Open community chat" aria-expanded="false" aria-controls="community-chat-panel" hidden><i class="bi bi-chat-dots-fill" aria-hidden="true"></i><span>Community chat</span></button>
    <noscript><p class="community-chat-noscript">Community chat preview requires JavaScript.</p></noscript>
</div>
